// A real twenty-face icosahedron mesh, projected and shaded without a network dependency.
const g=(1+Math.sqrt(5))/2;
const V=[[-1,g,0],[1,g,0],[-1,-g,0],[1,-g,0],[0,-1,g],[0,1,g],[0,-1,-g],[0,1,-g],[g,0,-1],[g,0,1],[-g,0,-1],[-g,0,1]].map(v=>{const l=Math.hypot(...v);return v.map(x=>x/l)});
const F=[[0,11,5],[0,5,1],[0,1,7],[0,7,10],[0,10,11],[1,5,9],[5,11,4],[11,10,2],[10,7,6],[7,1,8],[3,9,4],[3,4,2],[3,2,6],[3,6,8],[3,8,9],[4,9,5],[2,4,11],[6,2,10],[8,6,7],[9,8,1]];
const center=f=>f.map(i=>V[i]).reduce((a,v)=>a.map((n,j)=>n+v[j]),[0,0,0]).map(n=>n/3);
function rotate(v,x,y){let[a,b,c]=v;const u=a*Math.cos(y)+c*Math.sin(y),w=-a*Math.sin(y)+c*Math.cos(y);return[u,b*Math.cos(x)-w*Math.sin(x),b*Math.sin(x)+w*Math.cos(x)];}
export function fallbackRollDie(canvas,result,{instant=false,onDone=()=>{}}={}){const ctx=canvas.getContext('2d');canvas.width=440;canvas.height=440;let cancelled=false;const normal=center(F[Math.max(0,Math.min(19,result-1))]),fy=Math.atan2(-normal[0],normal[2]),fx=Math.atan2(normal[1],Math.hypot(normal[0],normal[2])),begin=performance.now(),duration=instant?1:1400;
 const draw=t=>{if(cancelled)return;const p=Math.min(1,(t-begin)/duration),ease=1-Math.pow(1-p,3),x=fx+(1-ease)*Math.PI*5,y=fy+(1-ease)*Math.PI*7,orbit=(1-p)*24;ctx.clearRect(0,0,440,440);ctx.save();ctx.translate(Math.cos(p*Math.PI*2)*orbit,Math.sin(p*Math.PI*2)*orbit);const pts=V.map(v=>rotate(v,x,y)),proj=v=>[220+v[0]*136/(1-v[2]*.17),220+v[1]*136/(1-v[2]*.17)],faces=F.map((f,i)=>({f,i,c:center(f),z:f.reduce((a,j)=>a+pts[j][2],0)/3})).sort((a,b)=>a.z-b.z);ctx.shadowColor='#9ec9c7';ctx.shadowBlur=15;for(const face of faces){const n=rotate(face.c,x,y);if(n[2]<-.08)continue;const lit=Math.max(0,n[2]*.65-n[0]*.3-n[1]*.35);ctx.beginPath();face.f.forEach((j,i)=>{const q=proj(pts[j]);i?ctx.lineTo(...q):ctx.moveTo(...q)});ctx.closePath();ctx.fillStyle=`rgb(${40+lit*70},${48+lit*82},${71+lit*100})`;ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#b4cad4aa';ctx.lineWidth=1.6;ctx.stroke();if(n[2]>.12){const q=proj(n);ctx.save();ctx.translate(...q);ctx.font=`700 ${15+12*n[2]}px SUIT,sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle=`rgba(235,243,232,${Math.min(1,n[2]*1.9)})`;ctx.fillText(String(face.i+1),0,0);ctx.restore();}}ctx.restore();if(p<1)requestAnimationFrame(draw);else onDone();};requestAnimationFrame(draw);return()=>{cancelled=true};}
